    "function commandSegments(command: string): string[] {",
    "  const parts: string[] = []",
    "  let current = \"\"",
    "  let quote: \"'\" | '\"' | null = null",
    "  for (let i = 0; i < command.length; i++) {",
    "    const ch = command[i]!",
    "    if (quote) {",
    "      current += ch",
    "      if (ch === quote && command[i - 1] !== \"\\\\\") quote = null",
    "      continue",
    "    }",
    "    if (ch === \"'\" || ch === '\"') {",
    "      quote = ch",
    "      current += ch",
    "      continue",
    "    }",
    "    const next = command[i + 1]",
    "    if ((ch === \"&\" && next === \"&\") || (ch === \"|\" && next === \"|\")) {",
    "      parts.push(current)",
    "      current = \"\"",
    "      i++",
    "      continue",
    "    }",
    "    if (ch === \"|\" || ch === \";\" || ch === \"\\n\") {",
    "      parts.push(current)",
    "      current = \"\"",
    "      continue",
    "    }",
    "    current += ch",
    "  }",
    "  parts.push(current)",
    "  return parts",
    "}",
